```php
function compressString($str) {
    $len = strlen($str);
    if ($len <= 2) return $str;
    $res = '';
    $count = 1;
    for ($i = 0; $i < $len; $i++) {
        if ($i + 1 < $len && $str[$i] === $str[$i + 1]) {
            $count++;
        } else {
            $res .= $str[$i] . $count;
            $count = 1;
        }
    }
    return strlen($res) < $len ? $res : $str;
}
```

